//! Known-answer vectors for chunk format v2 and v2 name metadata (task 1943),
//! plus the per-file-key name writer (task 1958, version 6) and a shared
//! folder's key id (task 2133, version 7).
//!
//! Published in `test-vectors/vectors.json` (version 10) so every client's v2
//! read path (web WASM, mobile UniFFI/Swift, desktop, cli) can pin the SAME
//! bytes. They are generated by core's real writer path with fixed inputs:
//!
//! - content: [`ChunkEncryptor`] with `with_recorded_pin(V2)` (the public way to
//!   write v2 while `WRITE_FORMAT` is still v1) and fixed frame nonces;
//! - name metadata: the [`encrypt_name_with_chunk_format`] rule (v2 pin →
//!   `chunk_format: 2`, name subkey) with a fixed nonce;
//! - name metadata under a GIVEN per-file key (task 1958, the rename writer
//!   `encrypt::encrypt_name_for`), for a key that is NOT derived from a master
//!   key, as a file-request or shared-folder file has: one v2-pinned, one
//!   unpinned (legacy raw key).
//!
//! The nonce seams ([`ChunkEncryptor::with_vector_nonces`],
//! [`encrypt_name_with_chunk_format_and_nonce`]) exist only under `cfg(test)` or
//! the `test-support` feature, as does this module. `published_v2_vectors_match_core`
//! regenerates every vector and compares it with the published file, so they
//! cannot drift from the writer.
//!
//! Regenerate (only when the format intentionally changes):
//! `cargo test -p beebeeb-core bless_v2_vectors_into_vectors_json -- --ignored`
//! (rewrites only these entries and the version), or
//! `cargo run -p beebeeb-core --bin generate_test_vectors --features test-support`.
//!
//! [`encrypt_name_with_chunk_format`]: crate::encrypt::encrypt_name_with_chunk_format

use serde_json::{Value, json};

use crate::chunk_stream::{ChunkEncryptor, ExpectedChunkFormat, VERSION_ID_LEN, chunk_aad_v2, derive_chunk_key_v2};
use crate::encrypt::{derive_name_key, encrypt_name_for_with_nonce, encrypt_name_with_chunk_format_and_nonce};
use crate::kdf::{MasterKey, derive_file_key};

/// The `version` of `test-vectors/vectors.json` that carries these vectors.
pub const VECTORS_FILE_VERSION: u64 = 10;

/// Names of the v2 vectors, in the order they are published.
pub const V2_VECTOR_NAMES: [&str; 16] = [
    "chunk_v2_stream",
    "chunk_v2_single_frame",
    "metadata_v2_name",
    "metadata_v2_name_filekey",
    "metadata_v1_name_filekey",
    "folder_key_id",
    // Version 8 (task 2237): a shared folder's search-index bucket key.
    "shared_folder_index_key",
    // Version 9 (task 2237b): the public folder-link key combiner.
    "combine_folder_link_key",
    "key_wrap_v1",
    "folder_link_passphrase",
    "folder_link_passphrase_nfd",
    "folder_custody_v1",
    "link_owner_key_v1",
    "link_owner_token_v1",
    "folder_child_file_v1",
    "folder_child_folder_v1",
];

/// A shared folder's key (bytes 0x80..=0x9f) for the `folder_key_id` vector.
const FOLDER_KEY: [u8; 32] = {
    let mut k = [0u8; 32];
    let mut i = 0;
    while i < 32 {
        k[i] = 0x80 + i as u8;
        i += 1;
    }
    k
};

/// A per-file key that is NOT derived from any master key (bytes 0x60..=0x7f),
/// like the random key of a file-request upload or a shared-folder file.
const GIVEN_FILE_KEY: [u8; 32] = {
    let mut k = [0u8; 32];
    let mut i = 0;
    while i < 32 {
        k[i] = 0x60 + i as u8;
        i += 1;
    }
    k
};

/// Fixed account master key of every v2 vector (bytes 0x40..=0x5f).
const MASTER_KEY: [u8; 32] = {
    let mut k = [0u8; 32];
    let mut i = 0;
    while i < 32 {
        k[i] = 0x40 + i as u8;
        i += 1;
    }
    k
};

/// Fixed file id of every v2 vector (the exact string fed to `derive_file_key`).
const FILE_ID: &str = "1908f00d-0000-4000-8000-000000001943";

const NOTE: &str = "Fixed nonces for a known-answer test; a real writer draws a fresh random nonce per frame. \
    Decrypt with the PUBLIC reader under ExpectedChunkFormat::V2 (frames in order, then finish), or per frame with \
    open_chunk(file_key, file_id, version_id, index, is_last, V2, frame).";

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// The three v2 vectors, as published.
pub fn v2_vectors() -> Vec<Value> {
    vec![
        chunk_stream_vector("chunk_v2_stream", &plaintext(71), 32, |i| [0xc0 | i as u8; 12]),
        chunk_stream_vector("chunk_v2_single_frame", &plaintext(20), 32, |_| [0xd0; 12]),
        metadata_v2_name(),
        metadata_name_filekey("metadata_v2_name_filekey", ExpectedChunkFormat::V2, [0x5b; 12]),
        metadata_name_filekey("metadata_v1_name_filekey", ExpectedChunkFormat::Unrecorded, [0x5c; 12]),
        folder_key_id_vector(),
        shared_folder_index_key_vector(),
        combine_folder_link_key_vector(),
        key_wrap_v1_vector(),
        folder_link_passphrase_vector(),
        folder_link_passphrase_nfd_vector(),
        purpose_wrap_vector(
            "folder_custody_v1",
            crate::kdf::FOLDER_CUSTODY_LABEL,
            "folder-2237c",
            &GIVEN_FILE_KEY,
        ),
        purpose_wrap_vector(
            "link_owner_key_v1",
            crate::kdf::LINK_OWNER_KEY_LABEL,
            "share-2237c",
            &FOLDER_KEY,
        ),
        purpose_wrap_vector(
            "link_owner_token_v1",
            crate::kdf::LINK_OWNER_TOKEN_LABEL,
            "share-2237c",
            b"AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8",
        ),
        folder_child_vector(1),
        folder_child_vector(2),
    ]
}

fn folder_child_vector(kind: u8) -> Value {
    let root = uuid::Uuid::parse_str("2237c000-0000-4000-8000-000000000001").unwrap();
    let item = uuid::Uuid::parse_str("2237c000-0000-4000-8000-000000000002").unwrap();
    let nonce = std::array::from_fn(|i| i as u8);
    let blob = crate::kdf::wrap_folder_child_with_nonce(
        &crate::kdf::FileKey::from_bytes(MASTER_KEY),
        root.as_bytes(),
        item.as_bytes(),
        kind,
        &crate::kdf::FileKey::from_bytes(GIVEN_FILE_KEY),
        &nonce,
    )
    .unwrap();
    let aad = [
        crate::kdf::FOLDER_CHILD_LABEL,
        root.as_bytes(),
        item.as_bytes(),
        &[kind],
    ]
    .concat();
    json!({"name": if kind==1 {"folder_child_file_v1"} else {"folder_child_folder_v1"}, "note":"L7: root UUID bytes || item UUID bytes || kind, after domain label; fixed nonce for public KAT only.", "folder_key_hex":hex(&MASTER_KEY),"child_key_hex":hex(&GIVEN_FILE_KEY),"shared_folder_id":root.to_string(),"item_id":item.to_string(),"kind":kind,"aad_hex":hex(&aad),"nonce_hex":hex(&nonce),"wrapped_hex":hex(&[blob.nonce,blob.ciphertext].concat())})
}

fn folder_link_passphrase_nfd_vector() -> Value {
    use unicode_normalization::UnicodeNormalization;
    let mut vector = folder_link_passphrase_vector();
    let passphrase = "folder café 2237".nfd().collect::<String>();
    let token = vector["token"].as_str().unwrap();
    let stretch = crate::kdf::derive_folder_link_passphrase_stretch(&passphrase, token).unwrap();
    vector["name"] = json!("folder_link_passphrase_nfd");
    vector["note"] = json!("NFC-normalize before Argon2id; this NFD spelling equals folder_link_passphrase.");
    vector["passphrase"] = json!(passphrase);
    vector["stretch_hex"] = json!(hex(&*stretch));
    vector["link_key_hex"] = json!(hex(&crate::kdf::combine_folder_link_key(&FOLDER_KEY, Some(&stretch))));
    vector
}

fn purpose_wrap_vector(name: &str, label: &[u8], record_id: &str, plaintext: &[u8]) -> Value {
    let context = [label, record_id.as_bytes()].concat();
    let mut key = zeroize::Zeroizing::new([0u8; 32]);
    hkdf::Hkdf::<sha2::Sha256>::new(None, &MASTER_KEY)
        .expand(&context, &mut *key)
        .unwrap();
    let nonce: [u8; 12] = std::array::from_fn(|i| i as u8);
    let blob = crate::kdf::purpose_wrap_with_nonce(
        &MasterKey::from_bytes(MASTER_KEY),
        label,
        record_id.as_bytes(),
        plaintext,
        &nonce,
    )
    .unwrap();
    json!({
        "name": name,
        "note": "L6: HKDF info and AES-GCM AAD both equal label || UTF-8 record id; fixed nonce for this public test only.",
        "master_key_hex": hex(&MASTER_KEY), "record_id": record_id,
        "label": std::str::from_utf8(label).unwrap(), "context_hex": hex(&context),
        "purpose_key_hex": hex(&*key), "plaintext_hex": hex(plaintext),
        "nonce_hex": hex(&nonce), "wrapped_hex": hex(&[blob.nonce, blob.ciphertext].concat()),
    })
}

fn key_wrap_v1_vector() -> Value {
    use crate::kdf::FileKey;
    let nonce: [u8; 12] = std::array::from_fn(|i| i as u8);
    let wrapper = FileKey::from_bytes(MASTER_KEY);
    let wrapped = crate::encrypt::seal_raw_with_nonce(&wrapper, &nonce, &GIVEN_FILE_KEY, &[]).unwrap();
    json!({
        "name": "key_wrap_v1",
        "note": "AES-256-GCM, no AAD; fixed nonce for this public test only.",
        "wrapper_key_hex": hex(&MASTER_KEY),
        "inner_key_hex": hex(&GIVEN_FILE_KEY),
        "nonce_hex": hex(&nonce),
        "wrapped_hex": hex(&wrapped),
    })
}

fn folder_link_passphrase_vector() -> Value {
    use crate::kdf::{
        FOLDER_LINK_PASSPHRASE_SALT_LABEL, combine_folder_link_key, derive_folder_link_passphrase_stretch,
    };
    use sha2::{Digest, Sha256};
    let token = "AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8";
    let passphrase = "folder café 2237";
    let salt = Sha256::new()
        .chain_update(token.as_bytes())
        .chain_update(FOLDER_LINK_PASSPHRASE_SALT_LABEL)
        .finalize();
    let stretch = derive_folder_link_passphrase_stretch(passphrase, token).unwrap();
    json!({
        "name": "folder_link_passphrase",
        "note": "Argon2id v19, 256 MiB, 4 iterations, 2 lanes, 32 bytes; token-bound SHA-256 salt then folder-link HKDF.",
        "token": token,
        "passphrase": passphrase,
        "k_c_hex": hex(&FOLDER_KEY),
        "salt_hex": hex(&salt[..16]),
        "stretch_hex": hex(&*stretch),
        "link_key_hex": hex(&combine_folder_link_key(&FOLDER_KEY, Some(&stretch))),
    })
}

/// A shared folder's per-bucket search-index key (task 2237):
/// `kdf::derive_shared_folder_index_key`, i.e. HKDF-SHA256 of the folder key
/// with no salt and the info `label || bucket as u32 LE`. Buckets 0, 7 and 63
/// pin the first, an interior and the last bucket of the default layout.
fn shared_folder_index_key_vector() -> Value {
    use crate::kdf::{FileKey, derive_shared_folder_index_key};

    let folder_key = FileKey::from_bytes(FOLDER_KEY);
    let buckets: Vec<Value> = [0u32, 7, 63]
        .into_iter()
        .map(|bucket| {
            json!({
                "bucket": bucket,
                "expected_hex": hex(derive_shared_folder_index_key(&folder_key, bucket).as_bytes()),
            })
        })
        .collect();
    json!({
        "name": "shared_folder_index_key",
        "note": "shared-folder search index key = HKDF-SHA256(ikm = folder key, salt = none, info = \
            \"beebeeb-shared-folder-index-v1\" || bucket as u32 LE), 32 bytes, one key per bucket.",
        "folder_key_hex": hex(&FOLDER_KEY),
        "salt": "none",
        "info": std::str::from_utf8(crate::kdf::SHARED_FOLDER_INDEX_KEY_INFO).expect("ascii info"),
        "buckets": buckets,
    })
}

/// The public folder-link key combiner (task 2237b): `kdf::combine_folder_link_key`
/// over `K_c` (the link fragment key) alone and with a 32-byte passphrase
/// stretch. `K_c` and the stretch use the same fixed byte ramps as the other
/// vectors (0x80..=0x9f and 0xa0..=0xbf).
fn combine_folder_link_key_vector() -> Value {
    use crate::kdf::combine_folder_link_key;

    let mut k_c = [0u8; 32];
    for (i, b) in k_c.iter_mut().enumerate() {
        *b = 0x80 + i as u8;
    }
    let mut stretch = [0u8; 32];
    for (i, b) in stretch.iter_mut().enumerate() {
        *b = 0xa0 + i as u8;
    }
    json!({
        "name": "combine_folder_link_key",
        "note": "folder link key = HKDF-SHA256(ikm = K_c [|| 32-byte Argon2id passphrase stretch], salt = none, \
            info = \"beebeeb-folder-link-key-v1\" || presence byte (0x00 without passphrase, 0x01 with)), 32 bytes.",
        "k_c_hex": hex(&k_c),
        "passphrase_stretch_hex": hex(&stretch),
        "salt": "none",
        "info": std::str::from_utf8(crate::kdf::FOLDER_LINK_KEY_INFO).expect("ascii info"),
        "expected_without_passphrase_hex": hex(&combine_folder_link_key(&k_c, None)),
        "expected_with_passphrase_hex": hex(&combine_folder_link_key(&k_c, Some(&stretch))),
    })
}

/// A shared folder's key id (task 2133): `folder_key::folder_key_id`, i.e.
/// HKDF-SHA256 of the folder key with no salt and the info below.
fn folder_key_id_vector() -> Value {
    json!({
        "name": "folder_key_id",
        "folder_key_hex": hex(&FOLDER_KEY),
        "salt": "none",
        "info": std::str::from_utf8(crate::folder_key::FOLDER_KEY_ID_INFO).expect("ascii info"),
        "expected_key_id_hex": hex(&crate::folder_key::folder_key_id(&FOLDER_KEY)),
        "note": "folder_key_id = HKDF-SHA256(ikm = folder key, salt = none, info = \"beebeeb/folder-key-id/v1\"), 32 \
            bytes. A one-way id of a folder key, meant for a server to compare folder keys without learning them. \
            Not secret, and never a key.",
    })
}

/// A name envelope written by `encrypt::encrypt_name_for` under
/// [`GIVEN_FILE_KEY`] (task 1958). A v2 pin records `chunk_format: 2` and is
/// sealed under the name subkey; `Unrecorded` is sealed under the raw key with
/// nothing recorded only while [`crate::encrypt::METADATA_SEAL_WRITE`] is
/// `Legacy` (the read-only phase): at the switch the unpinned vector changes,
/// and the drift guard says so.
fn metadata_name_filekey(name: &str, pin: ExpectedChunkFormat, nonce: [u8; 12]) -> Value {
    let file_key = crate::kdf::FileKey::from_bytes(GIVEN_FILE_KEY);
    let (filename, mime) = ("request-upload.pdf", "application/pdf");
    let name_encrypted =
        encrypt_name_for_with_nonce(&file_key, filename, Some(mime), pin, nonce).expect("seal name under a given key");
    json!({
        "name": name,
        "file_key_hex": hex(&GIVEN_FILE_KEY),
        "name_key_hex": hex(derive_name_key(&file_key).as_bytes()),
        "pin": pin.as_u8(),
        "nonce_hex": hex(&nonce),
        "name_encrypted": name_encrypted,
        "expected_name": filename,
        "expected_mime_type": mime,
        "expected_chunk_format": pin.as_u8(),
        "note": "Fixed nonce for a known-answer test. Written by encrypt_name_for(file_key, name, mime, pin), the \
            name writer for a key that is not derived from the master key (renames, file-request uploads). Read \
            with decrypt_file_metadata_with_key(file_key, name_encrypted): pin 2 opens under the name subkey only; \
            pin 0 opens under the raw file key while METADATA_SEAL_WRITE is Legacy (the read-only phase), and is \
            subkey-sealed after the switch, when this vector is re-published.",
    })
}

/// Deterministic plaintext of `len` bytes.
fn plaintext(len: usize) -> Vec<u8> {
    (0..len).map(|i| (i * 13 + 5) as u8).collect()
}

/// A v2 file written in `chunk_size` frames by the real writer, frame `i` sealed
/// with `nonce(i)`. Frame 0's nonce is the version id every frame binds.
fn chunk_stream_vector(name: &str, plaintext: &[u8], chunk_size: u64, nonce: impl Fn(usize) -> [u8; 12]) -> Value {
    let mk = MasterKey::from_bytes(MASTER_KEY);
    let file_key = derive_file_key(&mk, FILE_ID.as_bytes());
    let chunk_key = derive_chunk_key_v2(&file_key);
    let count = plaintext.len().div_ceil(chunk_size as usize).max(1);
    let nonces: Vec<[u8; 12]> = (0..count).map(&nonce).collect();
    let version_id: [u8; VERSION_ID_LEN] = nonces[0];

    let mut enc = ChunkEncryptor::for_push_with_chunk_size(&mk, FILE_ID, plaintext.len() as u64, chunk_size)
        .and_then(|e| e.with_recorded_pin(ExpectedChunkFormat::V2))
        .and_then(|e| e.with_vector_nonces(nonces.clone()))
        .expect("v2 vector encryptor");
    let mut frames = Vec::new();
    let mut wire = Vec::new();
    for (index, part) in plaintext.chunks(chunk_size as usize).enumerate() {
        let chunk = enc.push_chunk(part).expect("seal v2 frame");
        let is_last = index + 1 == count;
        frames.push(json!({
            "index": index,
            "is_last": is_last,
            "nonce_hex": hex(&nonces[index]),
            "aad_hex": hex(&chunk_aad_v2(FILE_ID.as_bytes(), &version_id, index as u32, is_last)),
            "plaintext_hex": hex(part),
            "frame_hex": hex(&chunk.data),
        }));
        wire.extend_from_slice(&chunk.data);
    }
    let summary = enc.finish().expect("finish v2 vector");
    assert_eq!(summary.chunk_count as usize, count);

    json!({
        "name": name,
        "chunk_format": 2,
        "master_key_hex": hex(&MASTER_KEY),
        "file_id": FILE_ID,
        "file_key_hex": hex(file_key.as_bytes()),
        "chunk_key_hex": hex(chunk_key.as_bytes()),
        "chunk_size": chunk_size,
        "chunk_count": count,
        "version_id_hex": hex(&version_id),
        "frames": frames,
        "wire_hex": hex(&wire),
        "plaintext_hex": hex(plaintext),
        "note": NOTE,
    })
}

/// A v2 file's name metadata: `{"chunk_format":2,"mime_type":..,"name":..}`
/// sealed under the name subkey, exactly the `name_encrypted` a server stores.
fn metadata_v2_name() -> Value {
    let mk = MasterKey::from_bytes(MASTER_KEY);
    let file_key = derive_file_key(&mk, FILE_ID.as_bytes());
    let nonce = [0x5a; 12];
    let (name, mime) = ("vector-v2.pdf", "application/pdf");
    let name_encrypted =
        encrypt_name_with_chunk_format_and_nonce(&mk, FILE_ID, name, Some(mime), ExpectedChunkFormat::V2, nonce)
            .expect("seal v2 name metadata");
    json!({
        "name": "metadata_v2_name",
        "master_key_hex": hex(&MASTER_KEY),
        "file_id": FILE_ID,
        "file_key_hex": hex(file_key.as_bytes()),
        "name_key_hex": hex(derive_name_key(&file_key).as_bytes()),
        "nonce_hex": hex(&nonce),
        "name_encrypted": name_encrypted,
        "expected_name": name,
        "expected_mime_type": mime,
        "expected_chunk_format": 2,
        "note": "Fixed nonce for a known-answer test. Read with decrypt_file_metadata(master_key, file_id, \
            name_encrypted): name subkey first; the pin it returns (V2) is what every content reader of the file \
            must use.",
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const VECTORS_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../test-vectors/vectors.json");

    fn published() -> Value {
        serde_json::from_str(&std::fs::read_to_string(VECTORS_PATH).expect("read vectors.json")).expect("parse")
    }

    /// The drift guard: every published v2 vector is exactly what core's writer
    /// produces from the fixed inputs today, and the file carries version 7.
    #[test]
    fn published_v2_vectors_match_core() {
        let doc = published();
        assert_eq!(doc["version"].as_u64(), Some(VECTORS_FILE_VERSION));
        let list = doc["vectors"].as_array().expect("vectors array");
        let regenerated = v2_vectors();
        assert_eq!(regenerated.len(), V2_VECTOR_NAMES.len());
        for (want, name) in regenerated.iter().zip(V2_VECTOR_NAMES) {
            let got = list
                .iter()
                .find(|v| v["name"] == name)
                .unwrap_or_else(|| panic!("{name} is missing from vectors.json (run the bless test)"));
            assert_eq!(got, want, "{name} drifted from core's v2 writer");
        }
    }

    /// Every content vector derives the SAME chunk key (one master key, one
    /// file id), so their fixed nonces must never repeat across vectors either
    /// (`with_vector_nonces` only sees one stream). E.g. `0xc0 | i` would reach
    /// the single-frame vector's `0xd0` at i = 16.
    #[test]
    fn fixed_nonces_never_repeat_under_one_key() {
        let mut seen = std::collections::HashSet::new();
        let mut frames = 0;
        for v in v2_vectors().iter().filter(|v| v.get("frames").is_some()) {
            for f in v["frames"].as_array().unwrap() {
                frames += 1;
                let n = f["nonce_hex"].as_str().unwrap().to_string();
                assert!(seen.insert(n.clone()), "nonce {n} repeats under the shared chunk key");
            }
        }
        assert_eq!(frames, 4, "3 stream frames + 1 single frame");
    }

    /// Task 1958: for a key derived from the master key, the per-file-key writer
    /// is byte-for-byte the master-key writer. With the published vector's own
    /// inputs it reproduces the published `metadata_v2_name` exactly.
    #[test]
    fn the_filekey_writer_reproduces_the_published_master_key_name() {
        let doc = published();
        let published = doc["vectors"]
            .as_array()
            .unwrap()
            .iter()
            .find(|v| v["name"] == "metadata_v2_name")
            .expect("metadata_v2_name published")
            .clone();
        let file_key = derive_file_key(&MasterKey::from_bytes(MASTER_KEY), FILE_ID.as_bytes());
        let got = encrypt_name_for_with_nonce(
            &file_key,
            "vector-v2.pdf",
            Some("application/pdf"),
            ExpectedChunkFormat::V2,
            [0x5a; 12],
        )
        .unwrap();
        assert_eq!(got, published["name_encrypted"].as_str().unwrap());
    }

    /// Writes the v2 vectors (and version 8) into `test-vectors/vectors.json`,
    /// leaving every other vector as it is. Run on purpose only.
    #[test]
    #[ignore]
    fn bless_v2_vectors_into_vectors_json() {
        let mut doc = published();
        let list = doc["vectors"].as_array_mut().expect("vectors array");
        list.retain(|v| !V2_VECTOR_NAMES.iter().any(|n| v["name"] == *n));
        list.extend(v2_vectors());
        doc["version"] = json!(VECTORS_FILE_VERSION);
        std::fs::write(VECTORS_PATH, serde_json::to_string_pretty(&doc).unwrap() + "\n").expect("write");
    }
}
